components.css:
.ds-quiet-nav { display: flex; align-items: center; gap: 1.5rem; }
.ds-quiet-nav-button { display: inline-flex; align-items: center; justify-content: center; padding: 0.3rem 0.6rem; border: none; border-radius: 0.25rem; background: transparent; color: var(--foreground, #111); font: inherit; cursor: pointer; transition: background-color 180ms ease-out; }
.ds-quiet-nav-button:hover { background: var(--accent, #e8e8e8); }
.ds-quiet-nav-button:focus-visible { outline: 2px solid var(--ring, #4c7c54); outline-offset: 3px; }

.ds-post-row { padding-bottom: 1.5rem; border-bottom: 1px solid var(--border, #ccc); }
.ds-post-meta { margin: 0 0 0.25rem; color: var(--muted-foreground, #666); font-size: 0.9rem; }
.ds-post-title { margin: 0.25rem 0; font-size: 1.35rem; font-weight: 400; line-height: 1.35; }
.ds-post-title a { color: inherit; text-decoration-color: var(--border, #ccc); text-underline-offset: 0.2em; }
.ds-post-title a:hover { color: var(--primary, #4c7c54); text-decoration-color: currentColor; }
.ds-post-desc { margin: 0.5rem 0 0; color: var(--muted-foreground, #666); }

.ds-code-block { position: relative; min-width: 0; margin-block: 1.5rem; }
.ds-code-pre { max-width: 100%; margin: 0; padding: 2.75rem 1rem 1rem; overflow-x: auto; border-radius: 0.35rem; background: #24292e; color: #e1e4e8; font-size: 0.9rem; line-height: 1.6; }
.ds-code-controls { position: absolute; top: 0.45rem; right: 0.65rem; display: flex; align-items: center; gap: 0.65rem; color: #e1e4e8; font-size: 0.75rem; line-height: 1; }
.ds-code-copy { display: inline-flex; align-items: center; justify-content: center; padding: 0.25rem 0.4rem; border: 1px solid rgb(255 255 255 / 25%); border-radius: 0.2rem; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.ds-code-copy:hover { background: rgb(255 255 255 / 10%); }
.ds-code-copy:focus-visible { outline: 2px solid var(--ring, #4c7c54); outline-offset: 2px; }

.ds-heading-group { display: flex; align-items: baseline; gap: 0.5rem; }
.ds-heading { flex: 1; min-width: 0; margin: 2rem 0 0.75rem; font-size: 1.35rem; font-weight: 400; line-height: 1.35; }
.ds-heading-copy { flex: none; display: inline-flex; align-items: center; justify-content: center; padding: 0.1rem 0.35rem; border: 1px solid transparent; border-radius: 0.2rem; background: transparent; color: var(--muted-foreground, #666); font: inherit; font-size: 0.72em; cursor: pointer; }
.ds-heading-copy:hover, .ds-heading-copy:focus-visible { border-color: var(--border, #ccc); background: var(--card, #fff); color: var(--foreground, #111); }

.ds-outline-toggle { display: inline-flex; align-items: center; justify-content: center; width: 3.5rem; min-height: 3.5rem; padding: 0.5rem; border: 1px solid var(--border, #ccc); border-radius: 50%; background: var(--card, #fff); color: var(--foreground, #111); font: inherit; font-size: 0.85rem; box-shadow: 0 2px 12px rgb(0 0 0 / 12%); cursor: grab; }
.ds-outline-toggle:hover { background: var(--muted, #eee); }
.ds-outline-toggle:focus-visible { outline: 2px solid var(--ring, #4c7c54); outline-offset: 3px; }

.ds-outline-list { display: grid; gap: 0.15rem; margin: 0; padding: 0.5rem; list-style: none; }
.ds-outline-children { display: grid; gap: 0.15rem; margin: 0.15rem 0 0.25rem 0.6rem; padding: 0 0 0 0.5rem; border-left: 1px solid var(--border, #ccc); list-style: none; }
.ds-outline-link { display: block; padding: 0.4rem 0.5rem; border-radius: 0.2rem; color: inherit; text-decoration: none; }
.ds-outline-link:hover, .ds-outline-link:focus-visible { background: var(--muted, #eee); }
.ds-outline-current { background: var(--muted, #eee); color: var(--primary, #4c7c54); font-weight: 600; }

.ds-notfound { max-width: 38rem; margin: 3rem auto; padding: clamp(1.25rem, 5vw, 2.5rem); border: 1px solid var(--border, #ccc); background: var(--card, #fff); }
.ds-error-code { margin: 0; color: var(--primary, #4c7c54); font-size: 1.25rem; font-weight: 700; }
.ds-notfound-title { margin: 0.25rem 0 0.75rem; font-size: clamp(2rem, 6vw, 3rem); line-height: 1.2; font-weight: 400; }
